import React from 'react';

import { Canvas } from '../../core/components/canvas/Canvas.js';
import { CanvasContext } from '../../core/components/canvas/CanvasContext.js';
import type { CanvasShape } from '../../core/components/canvas/types/canvas-shape.js';
import { divPlotLayout } from '../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { HeatmapDisplay } from '../components/displays/HeatmapDisplay.js';
import { useXYChartData } from '../hooks/useXYChartData.js';

//seriesAccessors

export function XYChartLayout() {
  const { height, width } = useGridPlotSize();
  const { seriesVariantsProps } = useXYChartData();

  return seriesVariantsProps.map((seriesProps, index) => {
    return (
      <div key={`display-${index}`} className={divPlotLayout}>
        {/* Consider refactor Canvas, and move context inside Canvas */}
        <CanvasContext.Provider
          value={{
            shapeRefs: new Map<string, React.MutableRefObject<CanvasShape>>(),
          }}
        >
          <Canvas width={width} height={height}>
            {/* TODO consider all variants */}
            <HeatmapDisplay seriesProps={seriesProps} />
          </Canvas>
        </CanvasContext.Provider>
      </div>
    );
  });
}

XYChartLayout['displayName'] = 'XYChartLayout';
